css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .cup { position: absolute; left: 16%; bottom: 6%; width: 62%; height: 44%; border-radius: 6px 6px 26% 26%; background: linear-gradient(#e2e8f0, #cbd5e1); }
.loader .cup::after { content: ''; position: absolute; left: 96%; top: 18%; width: 26%; height: 46%; border-radius: 0 50% 50% 0; border: 4px solid #cbd5e1; border-left-color: transparent; }
.loader .brew { position: absolute; left: 20%; bottom: 12%; width: 54%; height: 30%; border-radius: 4px 4px 24% 24%; background: var(--accent-2); animation: tea-brew calc(var(--loader-speed) * 3.2) ease-in-out infinite; }
.loader .string { position: absolute; left: 46%; top: 6%; width: 2%; height: 28%; border-radius: 2px; background: #94a3b8; transform-origin: 50% 0; animation: tea-sway calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader .bag { position: absolute; left: 38%; top: 30%; width: 18%; height: 22%; border-radius: 3px 3px 6px 6px; background: linear-gradient(var(--accent-2), var(--accent)); transform-origin: 50% -80%; animation: tea-dip calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
@keyframes tea-sway { 0%, 100% { transform: rotate(-7deg); } 50% { transform: rotate(7deg); } }
@keyframes tea-dip { 0%, 100% { transform: translateY(0) rotate(-7deg); } 50% { transform: translateY(26%) rotate(7deg); } }
@keyframes tea-brew { 0% { background: color-mix(in srgb, var(--accent-2) 25%, transparent); } 70%, 100% { background: var(--accent); } }
